40: function heightAt(x,z){
41:   const broad = Math.sin(x*.042+1.2)*2.1 + Math.cos(z*.036-.8)*2.5 + Math.sin((x+z)*.021)*1.5;
42:   const ridge = Math.sin(x*.015)*Math.cos(z*.018)*5.5;
