44:   const hill2 = Math.exp(-((x+55)**2+(z-39)**2)/1300)*6;
45:   const valley = -Math.exp(-((x+15)**2+(z-10)**2)/450)*3.2;
46:   return broad+ridge+hill1+hill2+valley;
