120: function createCharacter(kind='player') {
121:   const root=new THREE.Group(), rig=new THREE.Group();root.add(rig);
122:   const isPlayer=kind==='player', isMoss=kind==='mossman', torsoMat=isPlayer?mats.ape:isMoss?mats.mossman:mats.warden;
