174:   for(const t of treeSpots){const dx=pos.x-t.x,dz=pos.z-t.z,d=Math.hypot(dx,dz),min=playerRadius+t.r;if(d<min&&d>.001){pos.x=t.x+dx/d*min;pos.z=t.z+dz/d*min;}}
175:   pos.y=heightAt(pos.x,pos.z);return pos;
176: }
177: function updateCamera(dt){
