182:   // Sphere-like ray probe keeps the over-shoulder camera out of trunks and canopy.
183:   const rayDir=new THREE.Vector3().subVectors(desired,cameraTarget).normalize();let nearest=dist+1.2;
184:   for(const tree of treeSpots){const relX=tree.x-cameraTarget.x,relZ=tree.z-cameraTarget.z,t=relX*rayDir.x+relZ*rayDir.z;if(t>.3&&t<nearest){const px=cameraTarget.x+rayDir.x*t-tree.x,pz=cameraTarget.z+rayDir.z*t-tree.z;if(px*px+pz*pz<(tree.r+.28)**2)nearest=t;}}
185:   if(nearest<dist+1.2)desired.lerpVectors(cameraTarget,desired,Math.max(.18,(nearest-.45)/(dist+1.2)));
186:   camPos.lerp(desired,1-Math.exp(-dt*8));camera.position.copy(camPos);camera.lookAt(cameraTarget.x-Math.sin(yaw)*.65,cameraTarget.y+.35,cameraTarget.z-Math.cos(yaw)*.65);
187: }
