189:   forward.set(-Math.sin(yaw),0,-Math.cos(yaw));right.set(Math.cos(yaw),0,-Math.sin(yaw));moveDir.set(0,0,0).addScaledVector(forward,input.forward).addScaledVector(right,input.right);if(moveDir.lengthSq()>1)moveDir.normalize();
